(function(){
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function inline(s){
    s=esc(s);
    s=s.replace(/`([^`]+)`/g, function(m,c){return '<code>'+c+'</code>';});
    s=s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    s=s.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
    return s;
  }
  function render(md){
    var lines=String(md||'').split(/\r?\n/);
    var html='', i=0, listOpen=false, listType='';
    function closeList(){ if(listOpen){ html+='</'+listType+'>'; listOpen=false; listType=''; } }
    for(i=0;i<lines.length;i++){
      var l=lines[i];
      if(/^```/.test(l)){ closeList(); var buf=[]; i++; while(i<lines.length && !/^```/.test(lines[i])){ buf.push(esc(lines[i])); i++; } html+='<pre><code>'+buf.join('\n')+'</code></pre>'; continue; }
      var h=l.match(/^(#{1,6})\s+(.*)$/);
      if(h){ closeList(); var lv=h[1].length; html+='<h'+lv+'>'+inline(h[2])+'</h'+lv+'>'; continue; }
      if(/^>\s?/.test(l)){ closeList(); html+='<blockquote>'+inline(l.replace(/^>\s?/,''))+'</blockquote>'; continue; }
      if(/^[-*]\s+/.test(l)){ if(listOpen && listType!=='ul'){closeList();} if(!listOpen){html+='<ul>';listOpen=true;listType='ul';} html+='<li>'+inline(l.replace(/^[-*]\s+/,''))+'</li>'; continue; }
      if(/^\d+\.\s+/.test(l)){ if(listOpen && listType!=='ol'){closeList();} if(!listOpen){html+='<ol>';listOpen=true;listType='ol';} html+='<li>'+inline(l.replace(/^\d+\.\s+/,''))+'</li>'; continue; }
      if(/^(---|\*\*\*|___)$/.test(l.trim())){ closeList(); html+='<hr>'; continue; }
      if(l.trim()===''){ closeList(); continue; }
      closeList(); html+='<p>'+inline(l)+'</p>';
    }
    closeList();
    return {value: html};
  }
  var API={render:render, inline:inline, esc:esc};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__GlowForge__=API;
})();
